import{_ as o,a0 as l,w as p,s as a,ao as u,I as r,x as e,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Git 中的那些可怕的事 | LCTT x X-CMD","titleTemplate":false,"description":"Git 中的那些可怕的事 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 中的那些可怕的事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 中的那些可怕的事 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170116 Terrible Ideas in Git","title":"Git 中的那些可怕的事","tag":"201703","desc":""},"relativePath":"201703/20170116 Terrible Ideas in Git.md","filePath":"[post].md"}'),d={name:"201703/20170116 Terrible Ideas in Git.md"};function m(f,t,T,g,C,G){const i=l("Link");return p(),a("div",null,[t[13]||(t[13]=u('<h1 id="git-中的那些可怕的事" tabindex="-1">Git 中的那些可怕的事 <a class="header-anchor" href="#git-中的那些可怕的事" aria-label="Permalink to “Git 中的那些可怕的事”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/corey-quinn-lcna.png" alt="Corey Quinn"></p><p>在 LinuxCon 北美會議上 FutureAdvisor 的 Corey Quinn 説：“Git 的確讓你可以做一些超級強大的事。‘強大’，在這次講演中，這是一種説你愚蠢的委婉説法”。在使用 Git 時，誰沒有經歷讓你感覺自己像個傻子的時刻？當然，Git 是很棒的，每個人都在使用它，你可以用幾個基本命令完成你的大部分工作。但它也有一些強大的功能，讓我們覺得我們不知道我們在做什麼。</p><p>但這真的對我們來説不公平。沒有人會知道一切，每個人知道的都不同。Quinn 提醒我們：“在我許多講演的問答部分，人們有時舉手説：“嗯，我有一個傻問題。” 你看到人們在那裏説：“是啊！這是一個非常愚蠢的問題”。但是當他們得到答案時，那些這麼説的人也正在低頭記筆記。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/heffalump-git-corey-quinn_0.png" alt="Git"></p><p>Quinn 在演講的開始做了一些有趣的演示，演示了一些你可以用 Git 做到的可怕的事情，例如變基主幹然後進行強制推送來搞亂整個項目、胡亂輸入一些命令讓 git 吐槽、提交大型二進制文件等。然後他演示瞭如何使這些可怕的事情不怎麼可怕，如更加明智地管理大型二進制文件。“你可以提交大型二進制文件，你可以在 Git 中暴力提交，如果你需要存儲大的二進制文件，這裏有兩個工具會可以加速載入，一個是 git-annex，這是由 Debian 開發人員 Joey Hess 開發的，而 git-lfs 是由 GitHub 支持的。”</p><p>你經常同樣地錯誤輸入麼？例如，當你想要 <code>git status</code> 時卻輸入 <code>git stitis</code>？Quinn 有一個方案：“Git 有內置的別名支持，所以你可以將相對較長、複雜的東西命名為一個短的 Git 命令。” 此外，你還可以使用 shell 別名。</p><p>Quinn 説：“我們都聽説過變基主幹然後強制推送這樣的搞笑惡作劇，它會改變版本歷史，突然發生的事情讓所有人都措手不及，每個人都被捲入了這種混亂當中。一羣鯨魚被稱為“pod”，一羣烏鴉中被稱為“謀殺”，一羣開發者被稱為“合併衝突”……更嚴重的是，如果有人幹了這種事情，你有幾個選擇。包括從備份中恢復主幹，還原提交；或者把責任人從屋頂上尖叫着扔下去。或者，採取一定的預防措施並使用一個並不知名的 Git 功能稱為分支保護。啓用分支保護後，無法刪除或強制推送分支，並且在接受前，拉取請求（pull request）必須至少有一個審核。”</p><p>Quinn 演示了幾個更奇妙的有用的工具，使 Git 更高效和萬無一失，如 mr、vcsh 和定製的 shell 提示。你可以在下面看到完整的視頻，瞭解更多有趣的事情。</p><hr>',10)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(i,{href:"https://www.linux.com/news/event/LinuxCon-Europe/2016/terrible-ideas-git-0"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.linux.com/news/event/LinuxCon-Europe/2016/terrible-ideas-git-0",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),n(i,{href:"https://www.linux.com/users/cschroder"},{default:s(()=>[...t[2]||(t[2]=[e("CARLA SCHRODER",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),n(i,{href:"https://github.com/geekpi"},{default:s(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),n(i,{href:"https://github.com/Bestony"},{default:s(()=>[...t[4]||(t[4]=[e("Bestony",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const L=o(d,[["render",m]]);export{b as __pageData,L as default};
